const money = value => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value);
const currentDate = new Date();
const currentMonth = `${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`;
const backendConfig=window.GESTORPRO_CONFIG||{};
const supabaseClient=window.supabase?.createClient&&backendConfig.supabaseUrl&&backendConfig.supabasePublishableKey?window.supabase.createClient(backendConfig.supabaseUrl,backendConfig.supabasePublishableKey):null;
const requireAuth=backendConfig.requireAuth===true;
const authRedirectUrl=requireAuth?'https://gestor-pro-red.vercel.app':window.location.origin;
const allowedGoogleEmail=String(backendConfig.allowedGoogleEmail||'').trim().toLowerCase();
let currentUser=null;
let accounts = [];
let transactions = [];
let currentPage='inicio',toastTimer,pendingAssistantSuggestion=null,lastSuggestion=null,openFinanceStatus=null,openFinanceLoading=false,cloudSyncReady=false,cloudSyncTimer=null;
const LOCAL_DATA_KEY='gestorpro.personal.v1';
const OPEN_FINANCE_ITEMS_KEY='gestorpro.openfinance.items.v1';
const SAVINGS_POTS_KEY='gestorpro.savings-pots.v1';
const CATEGORY_OVERRIDES_KEY='gestorpro.transaction-categories.v1';
const SYNCED_SNAPSHOT_KEY='gestorpro.synced-snapshot.v1';
let openFinanceItems=[];
let openFinanceData=[];
let savingsPots=[];
let transactionCategoryOverrides={};
const assistantMessages=[{role:'assistant',text:'Oi! Posso ajudar a sugerir uma categoria para um lançamento. Escreva a descrição como aparece no seu extrato; se faltar contexto, eu aviso.'}];
const pageNames={inicio:'Visão geral',contas:'Minhas contas',lancamentos:'Lançamentos',assistente:'Assistente de categorias',openfinance:'Open Finance',planejamento:'Caixinhas e metas',relatorios:'Análise financeira',configuracoes:'Configurações'};
function loadLocalData(){try{const saved=JSON.parse(localStorage.getItem(LOCAL_DATA_KEY)||'null');if(saved&&Array.isArray(saved.accounts)&&Array.isArray(saved.transactions)){const demoAccountIds=new Set(['acc-1','acc-2','acc-3']);const demoTransactionIds=new Set(['tx-1','tx-2','tx-3','tx-4','tx-5','tx-6','tx-7','tx-8']);accounts=saved.accounts.filter(account=>!demoAccountIds.has(account.id));transactions=saved.transactions.filter(transaction=>!demoTransactionIds.has(transaction.id));if(accounts.length!==saved.accounts.length||transactions.length!==saved.transactions.length)saveLocalData();}}catch(error){console.warn('Não foi possível ler os dados locais do GestorPro.',error);}}
function loadOpenFinanceItems(){try{const saved=JSON.parse(localStorage.getItem(OPEN_FINANCE_ITEMS_KEY)||'[]');if(Array.isArray(saved))openFinanceItems=saved.filter(item=>item&&typeof item.id==='string');}catch(error){console.warn('Não foi possível ler as conexões Open Finance locais.',error);}}
function saveOpenFinanceItems(){localStorage.setItem(OPEN_FINANCE_ITEMS_KEY,JSON.stringify(openFinanceItems));queueCloudSync();}
function saveLocalData(){try{localStorage.setItem(LOCAL_DATA_KEY,JSON.stringify({version:1,accounts,transactions,updatedAt:new Date().toISOString()}));queueCloudSync();return true;}catch(error){showToast('Não foi possível salvar. Verifique o espaço disponível no navegador.');return false;}}
function loadSavingsPots(){try{const saved=JSON.parse(localStorage.getItem(SAVINGS_POTS_KEY)||'[]');if(Array.isArray(saved))savingsPots=saved.filter(pot=>pot&&typeof pot.id==='string');}catch(error){console.warn('Não foi possível ler as caixinhas locais.',error);}}
function saveSavingsPots(){try{localStorage.setItem(SAVINGS_POTS_KEY,JSON.stringify(savingsPots));queueCloudSync();return true;}catch(error){showToast('Não foi possível salvar as caixinhas neste navegador.');return false;}}
function loadCategoryOverrides(){try{const saved=JSON.parse(localStorage.getItem(CATEGORY_OVERRIDES_KEY)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))transactionCategoryOverrides=saved;}catch(error){console.warn('Não foi possível ler as categorias personalizadas.',error);}}
function saveCategoryOverrides(){try{localStorage.setItem(CATEGORY_OVERRIDES_KEY,JSON.stringify(transactionCategoryOverrides));queueCloudSync();return true;}catch(error){showToast('Não foi possível salvar a categoria neste navegador.');return false;}}
function workspaceSnapshot(){return {accounts,transactions,savingsPots,transactionCategoryOverrides,openFinanceItems};}
function hasLocalWorkspaceData(){return accounts.length>0||transactions.length>0||savingsPots.length>0||openFinanceItems.length>0||Object.keys(transactionCategoryOverrides).length>0;}
function queueCloudSync(){if(!cloudSyncReady||!supabaseClient||!isAllowedGoogleUser())return;clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(()=>saveCloudWorkspace().catch(error=>showToast(error.message||'Não foi possível sincronizar seus dados.')),700);}
async function saveCloudWorkspace(){if(!supabaseClient||!isAllowedGoogleUser())return;const payload=workspaceSnapshot();const {error}=await supabaseClient.from('personal_finance_data').upsert({user_id:currentUser.id,payload,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)throw new Error('Não consegui sincronizar seus dados. Confira se a tabela e as políticas RLS do Supabase foram configuradas.');localStorage.setItem(SYNCED_SNAPSHOT_KEY,JSON.stringify(payload));}async function loadCloudWorkspace(user){
  if(!supabaseClient||!user||!isAllowedGoogleUser(user))return;
  cloudSyncReady=false;
  try{
    const {data,error}=await supabaseClient.from('personal_finance_data').select('payload').eq('user_id',user.id).maybeSingle();
    if(error)throw new Error('Não consegui acessar o armazenamento seguro do Supabase. Confira a tabela e as políticas RLS.');
    const local=workspaceSnapshot();
    const localChanged=hasLocalWorkspaceData()&&JSON.stringify(local)!==localStorage.getItem(SYNCED_SNAPSHOT_KEY);
    let remote=data?.payload||null;
    if(remote&&localChanged){
      if(confirm('Há dados novos neste navegador e na sua conta online. Mesclar os registros locais com os dados online e salvar a combinação no Supabase?')){
        const merge=(left,right)=>{const records=new Map();[...(Array.isArray(left)?left:[]),...(Array.isArray(right)?right:[])].forEach(record=>{if(record?.id)records.set(record.id,record);});return [...records.values()]};
        remote={...remote,accounts:merge(remote.accounts,local.accounts),transactions:merge(remote.transactions,local.transactions),savingsPots:merge(remote.savingsPots,local.savingsPots),transactionCategoryOverrides:{...(remote.transactionCategoryOverrides||{}),...local.transactionCategoryOverrides},openFinanceItems:merge(remote.openFinanceItems,local.openFinanceItems)};
      }else if(!confirm('Usar os dados online neste aparelho? Isso substituirá os dados locais exibidos aqui. Faça uma cópia de segurança antes, se precisar preservá-los.')){showToast('Sincronização cancelada; os dados locais foram mantidos.');render(currentPage);return;}
    }
    if(!remote){if(hasLocalWorkspaceData()&&!confirm('Para acessar seus dados em outros aparelhos, o GestorPro precisa enviar os registros deste navegador para o Supabase da sua conta. Deseja guardar seus dados financeiros online?')){showToast('Você entrou, mas a sincronização online ficou desligada.');render(currentPage);return;}remote=local;}
    accounts=Array.isArray(remote.accounts)?remote.accounts:[];transactions=Array.isArray(remote.transactions)?remote.transactions:[];savingsPots=Array.isArray(remote.savingsPots)?remote.savingsPots:[];transactionCategoryOverrides=remote.transactionCategoryOverrides&&typeof remote.transactionCategoryOverrides==='object'?remote.transactionCategoryOverrides:{};openFinanceItems=Array.isArray(remote.openFinanceItems)?remote.openFinanceItems:[];
    localStorage.setItem(LOCAL_DATA_KEY,JSON.stringify({version:1,accounts,transactions,updatedAt:new Date().toISOString()}));localStorage.setItem(SAVINGS_POTS_KEY,JSON.stringify(savingsPots));localStorage.setItem(CATEGORY_OVERRIDES_KEY,JSON.stringify(transactionCategoryOverrides));localStorage.setItem(OPEN_FINANCE_ITEMS_KEY,JSON.stringify(openFinanceItems));
    cloudSyncReady=true;await saveCloudWorkspace();showToast('Dados sincronizados com sua conta Google.');render(currentPage);if(openFinanceItems.length)loadOpenFinancePage(true);
  }catch(error){cloudSyncReady=false;showToast(error.message||'Falha ao sincronizar os dados.');render(currentPage);}
}function initials(text){return text.split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase()}
function connectedAccounts(){return openFinanceData.flatMap(item=>(item.accounts||[]).map(account=>({id:`pluggy-${account.id}`,sourceId:account.id,name:account.name||account.marketingName||'Conta conectada',institution:item.institution,type:account.type==='CREDIT'?'Cartão de crédito':account.subtype||'Conta bancária',balance:Number(account.balance)||0,color:'blue',isCredit:account.type==='CREDIT',connected:true})));}
function displayAccounts(){return [...accounts,...connectedAccounts()]}
const spendingCategories=['Alimentação','Alimentação fora','Moradia','Contas','Transporte','Saúde','Educação','Compras','Lazer','Assinaturas','Cuidados pessoais','Impostos e taxas','Salário','Transferências','Transferência entre contas','Outros','Sem categoria'];
function inferredCategory(description){const text=String(description||'').toLocaleLowerCase('pt-BR');const rules=[[/mercado|supermercado|feira|hortifruti|carrefour|atacad[aã]o|ass[aã]i/,'Alimentação'],[/ifood|restaurante|lanchonete|padaria|caf[eé]|burger|pizzaria/,'Alimentação fora'],[/aluguel|condom[ií]nio|imobili[aá]ria/,'Moradia'],[/farm[aá]cia|consulta|m[eé]dic|hospital|laborat[oó]rio/,'Saúde'],[/uber|99\s|combust[ií]vel|posto|metr[oô]|[oô]nibus|estacionamento/,'Transporte'],[/sal[aá]rio|folha de pagamento/,'Salário'],[/energia|conta de luz|internet|[aá]gua|telefone|celular/,'Contas'],[/netflix|spotify|streaming|assinatura/,'Assinaturas'],[/escola|faculdade|curso|mensalidade escolar/,'Educação'],[/cinema|show|teatro|parque|ingresso/,'Lazer'],[/transfer[eê]ncia|\bted\b|\bdoc\b/,'Transferências']];for(const [pattern,category] of rules)if(pattern.test(text))return category;return 'Sem categoria';}
function internalTransfer(item){const text=`${item.description||''} ${item.operationType||''} ${item.category||''}`.toLocaleLowerCase('pt-BR');return item.kind==='transferencia'||/transfer[eê]ncia entre contas|entre minhas contas|conta pr[oó]pria|transfer[êe]ncia interna|internal transfer|own account/.test(text)}
function liveTransactions(){return openFinanceData.flatMap(item=>(item.accounts||[]).flatMap(account=>(account.transactions||[]).map(transaction=>{const id=`pluggy-${transaction.id}`,description=transaction.description||'Movimentação bancária';const kind=internalTransfer(transaction)?'transferencia':transaction.type==='CREDIT'?'entrada':'saida';const rawCategory=transaction.category||transaction.categoryDescription;return {id,description,category:transactionCategoryOverrides[id]||rawCategory||inferredCategory(description),accountId:`pluggy-${account.id}`,date:String(transaction.date||'').slice(0,10),kind,amount:Math.abs(Number(transaction.amount)||0),source:'openfinance',operationType:transaction.operationType||''};}))).filter(transaction=>transaction.date)}
function allTransactions(){return [...transactions,...liveTransactions()].map(item=>{const category=transactionCategoryOverrides[item.id]||item.category||inferredCategory(item.description);return {...item,category,kind:item.kind==='transferencia'||category==='Transferência entre contas'?'transferencia':item.kind};}).sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
function accountName(id){return displayAccounts().find(account=>account.id===id)?.name||'Conta removida'}
function monthTransactions(){return allTransactions().filter(item=>item.date.startsWith(currentMonth))}
function totals(items){return items.reduce((result,item)=>{if(item.kind==='transferencia')return result;result[item.kind]+=item.amount;return result},{entrada:0,saida:0})}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><p class="eyebrow">SUAS FINANÇAS PESSOAIS</p><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function button(text,action,primary=false){return `<button class="button ${primary?'primary':''}" data-action="${action}">${text}</button>`}
function stat(label,value,detail,icon,color){return `<article class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ic-${color}">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot"><span class="compare">${detail}</span></div></article>`}
function dashboard(){const month=totals(monthTransactions());const visibleAccounts=displayAccounts();const total=visibleAccounts.filter(account=>!account.isCredit).reduce((sum,account)=>sum+Number(account.balance),0);const net=month.entrada-month.saida;const investments=openFinanceData.flatMap(investmentPositions).filter(investment=>investment.status!=='TOTAL_WITHDRAWAL');const investedTotal=investments.reduce((sum,investment)=>sum+Number(investment.balance||0),0);const manualTotal=savingsPots.reduce((sum,pot)=>sum+Number(pot.balance||0),0);const hasInvestmentErrors=openFinanceData.some(item=>item.error||item.investmentError);const investmentSummary=`<div class="simple-grid investment-summary"><article class="simple-card investment-total"><small>Minhas caixinhas · valor informado por você</small><strong>${money(manualTotal)}</strong><p>${savingsPots.length?`${savingsPots.length} meta(s) acompanhada(s) manualmente`:'Cadastre suas Caixinhas e metas para acompanhar a evolução.'}</p><button class="button" data-page="planejamento">Acompanhar metas →</button></article>${investments.length?`<article class="simple-card"><small>Investimentos sincronizados pelo Meu Pluggy</small><strong>${money(investedTotal)}</strong><p>${investments.length} posição(ões) recebida(s) pela Pluggy</p></article>`:`<article class="simple-card"><small>Meu Pluggy</small><strong>Caixinhas não recebidas</strong><p>${hasInvestmentErrors?'Não foi possível atualizar os investimentos.':'Os valores das Caixinhas ainda não vieram na sincronização.'}</p><a data-page="openfinance">Ver conexão →</a></article>`}</div>`;return `${heading('Olá! 👋','Uma visão simples e organizada das suas contas.',`${button('<span class="plus">＋</span>Novo lançamento','new-transaction',true)}${button('<span class="plus">＋</span>Adicionar conta','new-account')}`)}
  <section class="stats-grid">${stat('Saldo disponível',money(total),'Contas conectadas e manuais','▣','blue')}${stat('Entradas no mês',money(month.entrada),'Extrato e lançamentos locais','↙','green')}${stat('Saídas no mês',money(month.saida),'Extrato e lançamentos locais','↗','orange')}${stat('Resultado do mês',money(net),net>=0?'Entradas menos saídas':'Saídas acima das entradas','◉','purple')}</section>
  <section class="section-title"><h2>Gastos para revisar</h2><a data-page="relatorios">Abrir análise →</a></section>${spendingAlertsMarkup()}
  <section class="section-title"><h2>Investimentos e caixinhas</h2><a data-page="openfinance">Ver Open Finance →</a></section>${investmentSummary}
  <section class="section-title"><h2>Minhas contas</h2><a data-page="contas">Ver todas →</a></section><div class="simple-grid account-grid">${visibleAccounts.length?visibleAccounts.map(accountCard).join(''):'<p class="empty-state">Nenhuma conta carregada. Abra Open Finance para buscar seus dados reais.</p>'}</div>
  <section class="section-title"><h2>Lançamentos recentes</h2><a data-page="lancamentos">Ver todos →</a></section>${transactionTable(allTransactions().slice(0,5))}`}
function accountCard(account){return `<article class="simple-card account-card"><div class="account-card-top"><span class="stat-icon ic-${account.color}">▣</span><span class="account-type">${account.type}</span></div><small>${account.institution}</small><strong>${money(Number(account.balance))}</strong><p>${account.name}</p></article>`}
function transactionTable(items){return `<div class="panel table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>DESCRIÇÃO</th><th>CATEGORIA</th><th>CONTA</th><th>DATA</th><th>VALOR</th></tr></thead><tbody>${items.length?items.map(item=>`<tr><td><div class="client-cell"><span class="mini-avatar ${item.kind==='entrada'?'income-avatar':item.kind==='transferencia'?'transfer-avatar':'expense-avatar'}">${item.kind==='entrada'?'↓':item.kind==='transferencia'?'⇄':'↑'}</span><b>${escapeHTML(item.description)}</b></div></td><td><select class="category-select" aria-label="Categoria do lançamento" data-transaction-category="${escapeHTML(item.id)}">${[...new Set([...spendingCategories,item.category])].map(category=>`<option value="${escapeHTML(category)}" ${item.category===category?'selected':''}>${escapeHTML(category)}</option>`).join('')}</select></td><td class="muted">${escapeHTML(accountName(item.accountId))}${item.toAccountId?` → ${escapeHTML(accountName(item.toAccountId))}`:''}</td><td class="muted">${formatDate(item.date)}</td><td><b class="${item.kind==='entrada'?'income-text':item.kind==='transferencia'?'transfer-text':'expense-text'}">${item.kind==='entrada'?'+':item.kind==='transferencia'?'↔':'−'} ${money(item.amount)}</b></td></tr>`).join(''):`<tr><td colspan="5" class="empty-state">Nenhum lançamento para mostrar.</td></tr>`}</tbody></table></div></div>`}
function formatDate(date){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${date}T12:00:00`))}
function previousMonthKeys(count=3){const result=[];const date=new Date();date.setDate(1);for(let index=0;index<count;index++){date.setMonth(date.getMonth()-1);result.push(`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`);}return result;}
function spendingAnalysis(items=allTransactions()){const expenses=items.filter(item=>item.kind==='saida'&&!internalTransfer(item)&&item.date);const current=expenses.filter(item=>item.date.startsWith(currentMonth));const currentTotals={};current.forEach(item=>currentTotals[item.category]=(currentTotals[item.category]||0)+Number(item.amount||0));const priorMonths=previousMonthKeys(3);const monthsWithData=new Set(expenses.filter(item=>priorMonths.includes(item.date.slice(0,7))).map(item=>item.date.slice(0,7)));const trends=[];if(monthsWithData.size>=2&&new Date().getDate()>=15){for(const [category,amount] of Object.entries(currentTotals)){const previous=priorMonths.map(month=>expenses.filter(item=>item.category===category&&item.date.startsWith(month)).reduce((sum,item)=>sum+Number(item.amount||0),0));const average=previous.reduce((sum,value)=>sum+value,0)/previous.length;if(amount-average>=100&&amount>average*1.5)trends.push({type:'category',category,amount,average,delta:amount-average});}}
 const outliers=[];const today=new Date();expenses.filter(item=>item.date.startsWith(currentMonth)).forEach(item=>{const date=new Date(`${item.date}T12:00:00`);const age=(today-date)/(24*60*60*1000);if(age<0||age>90)return;const prior=expenses.filter(other=>other.category===item.category&&other.id!==item.id&&new Date(`${other.date}T12:00:00`)<date&&(date-new Date(`${other.date}T12:00:00`))/(24*60*60*1000)<=90).map(other=>Number(other.amount)||0).sort((a,b)=>a-b);if(prior.length<3)return;const middle=Math.floor(prior.length/2),median=prior.length%2?prior[middle]:(prior[middle-1]+prior[middle])/2;if(Number(item.amount)>=100&&Number(item.amount)>median*2.5&&Number(item.amount)-median>=100)outliers.push({type:'transaction',item,median});});return {currentTotals,trends,outliers,historyReady:monthsWithData.size>=2};}
function spendingAlertsMarkup(){const analysis=spendingAnalysis();const alerts=[...analysis.trends.map(alert=>`<article class="spending-alert"><b>Gasto acima do seu padrão · ${escapeHTML(alert.category)}</b><p>Este mês: ${money(alert.amount)}. Média dos 3 meses anteriores: ${money(alert.average)} — aumento de ${money(alert.delta)}. Vale revisar os lançamentos desta categoria.</p></article>`),...analysis.outliers.map(alert=>`<article class="spending-alert"><b>Compra acima do seu padrão · ${escapeHTML(alert.item.category)}</b><p>${escapeHTML(alert.item.description)} em ${formatDate(alert.item.date)}: ${money(alert.item.amount)}. Seus outros gastos recentes nesta categoria têm mediana de ${money(alert.median)}. Confirme se a categoria está correta.</p></article>`)];return alerts.length?`<div class="spending-alerts">${alerts.slice(0,6).join('')}</div>`:`<div class="panel openfinance-empty"><b>${analysis.historyReady?'Nenhum gasto fora do padrão detectado':'Ainda estou aprendendo seu padrão de gastos'}</b><p>${analysis.historyReady?'Não encontrei valores que ultrapassem os critérios de comparação no período disponível. Revise as categorias para melhorar a análise.':'São necessários lançamentos categorizados de meses anteriores para comparar seus gastos. Os alertas aparecem só quando houver histórico suficiente.'}</p></div>`}
function accountsPage(){const visibleAccounts=displayAccounts();const total=visibleAccounts.filter(account=>!account.isCredit).reduce((sum,account)=>sum+Number(account.balance),0);return `${heading('Minhas contas','Saldos recebidos do Meu Pluggy e contas adicionadas manualmente.',button('<span class="plus">＋</span>Adicionar conta','new-account',true))}<div class="simple-grid account-grid">${visibleAccounts.map(accountCard).join('')}<article class="simple-card account-total"><small>Saldo disponível somado</small><strong>${money(total)}</strong><p>Não inclui limites de crédito nem investimentos</p></article></div><section class="section-title"><h2>Últimos lançamentos</h2><a data-page="lancamentos">Ver todos →</a></section>${transactionTable(allTransactions().slice(0,6))}`}
function transactionsPage(){const month=totals(monthTransactions());return `${heading('Lançamentos','Revise e ajuste a categoria de cada movimentação. Transferências entre suas contas não contam como gastos.',button('<span class="plus">＋</span>Novo lançamento','new-transaction',true))}<div class="stats-grid">${stat('Entradas no mês',money(month.entrada),'Extrato e lançamentos locais','↙','green')}${stat('Saídas no mês',money(month.saida),'Extrato e lançamentos locais','↗','orange')}${stat('Lançamentos',String(monthTransactions().length),'Neste mês','⇄','blue')}${stat('Contas vinculadas',String(displayAccounts().length),'No seu controle','▣','purple')}</div><section class="section-title"><h2>Histórico</h2><div class="toolbar"><input class="input search" id="transaction-search" placeholder="⌕  Buscar lançamento..."></div></section><div id="transaction-table">${transactionTable(allTransactions())}</div>`}
function planningPage(){const total=savingsPots.reduce((sum,pot)=>sum+Number(pot.balance||0),0);return `${heading('Caixinhas e metas','Acompanhe seus valores e veja o progresso rumo aos seus objetivos.',button('<span class="plus">＋</span>Adicionar caixinha','new-savings-pot',true))}<div class="assistant-note"><span>✦</span><div><b>Acompanhamento pessoal</b><p>Os valores desta seção são informados por você e ficam salvos neste navegador. Eles não foram sincronizados nem confirmados pelo Nubank ou pela Pluggy.</p></div></div><div class="simple-grid investment-summary"><article class="simple-card investment-total"><small>Total informado nas minhas caixinhas</small><strong>${money(total)}</strong><p>${savingsPots.length} caixinha(s) acompanhada(s)</p></article></div>${savingsPots.length?`<div class="simple-grid investment-grid">${savingsPots.map(pot=>{const balance=Number(pot.balance)||0,goal=Number(pot.goal)||0,percent=goal?Math.min(100,Math.round(balance/goal*100)):0;const history=Array.isArray(pot.history)?pot.history:[];const first=history.length?Number(history[0].balance)||0:balance;const change=balance-first;return `<article class="simple-card investment-card savings-pot-card"><small>Caixinha · atualização manual</small><strong>${money(balance)}</strong><p><b>${escapeHTML(pot.name)}</b></p>${goal?`<p>Meta: ${money(goal)} · ${percent}% concluída</p><div class="goal-progress"><span style="width:${percent}%"></span></div>`:'<p>Defina uma meta para acompanhar o percentual concluído.</p>'}<p class="muted">${history.length>1?`Evolução registrada: ${change>=0?'+':''}${money(change)}`:'Atualize o saldo periodicamente para registrar sua evolução.'} · atualizado em ${formatDate(String(pot.updatedAt||'').slice(0,10))}</p><button class="button" data-action="update-savings-pot" data-id="${escapeHTML(pot.id)}">Atualizar valor</button> <button class="button" data-action="delete-savings-pot" data-id="${escapeHTML(pot.id)}">Excluir</button></article>`}).join('')}</div>`:'<div class="panel openfinance-empty"><b>Adicione sua primeira Caixinha</b><p>Informe o saldo atual e, se quiser, uma meta. A cada atualização, o GestorPro registra um ponto de evolução para você acompanhar seu progresso.</p></div>'}<p class="openfinance-footnote">O acompanhamento manual serve para organização pessoal. Enquanto o Meu Pluggy não enviar os RDBs, esses valores não aparecem como dados bancários sincronizados.</p>`}
function escapeHTML(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function suggestCategory(description){const text=String(description||'').toLocaleLowerCase('pt-BR');const own=/minha conta|minhas contas|entre contas|conta própria|conta de reserva|para reserva|reserva de emergência/.test(text);if(own&&/transfer|pix|ted|doc/.test(text))return {category:'Transferência entre contas',kind:'transferencia',reason:'Parece uma movimentação entre contas suas, que deve ser excluída da soma de gastos e rendas.',ambiguous:false};const category=inferredCategory(text);if(category!=='Sem categoria')return {category,kind:category==='Salário'?'entrada':'saida',reason:`Classifiquei como ${category} com base na descrição. Confira se está correto.`,ambiguous:false};if(/transfer|pix|ted|doc/.test(text))return {category:'Transferências',kind:null,reason:'Um Pix pode ser uma compra, pagamento ou transferência entre suas contas. Confirme o contexto antes de categorizar.',ambiguous:true};return {category:'Sem categoria',kind:null,reason:'Não encontrei contexto suficiente na descrição. Escolha a categoria correta para melhorar sua análise de gastos.',ambiguous:true};}
function assistantPage(){const live=Boolean(supabaseClient&&currentUser);const note=live?'Com a função publicada, a mensagem atual e até 8 mensagens anteriores desta conversa serão enviadas à OpenAI para sugerir uma categoria. Evite incluir números de conta, cartão, códigos ou outros dados de acesso.':'A conexão real usa sua sessão do Supabase e uma função segura. Sem essa configuração, esta tela usa sugestões locais de demonstração.';return `${heading('Assistente de categorias','Converse para entender e categorizar seus lançamentos.') }<div class="assistant-note"><span>✦</span><div><b>${live?'Sessão Supabase ativa':'Conexão do assistente'}</b><p>${note}${supabaseClient&&!currentUser?' Acesse Configurações para entrar ou criar sua conta.':''}</p></div></div><section class="chat-panel"><div class="chat-messages" id="chat-messages">${assistantMessages.map(message=>`<div class="chat-message ${message.role}"><span class="chat-avatar">${message.role==='assistant'?'✦':'EU'}</span><div class="chat-bubble">${escapeHTML(message.text)}${message.category?`<div class="suggestion-card"><small>SUGESTÃO DE CATEGORIA${message.confidence?` · CONFIANÇA ${escapeHTML(message.confidence.toUpperCase())}`:''}</small><b>${escapeHTML(message.category)}</b><p>${escapeHTML(message.reason)}</p><button class="button primary" data-action="use-suggestion" data-description="${escapeHTML(message.description)}" data-category="${escapeHTML(message.category)}" data-kind="${message.kind||''}">Revisar no lançamento</button></div>`:''}</div></div>`).join('')}</div><div class="chat-examples"><span>Experimente:</span><button class="chip" data-prompt="Pix para minha conta de reserva">Pix para minha reserva</button><button class="chip" data-prompt="Transferência Pix para mercado">Pix para mercado</button><button class="chip" data-prompt="Pagamento Netflix mensal">Assinatura mensal</button></div><form class="chat-composer" id="assistant-form"><input id="assistant-input" name="message" maxlength="500" placeholder="Descreva a movimentação do extrato..." autocomplete="off" required><button class="button primary" type="submit" aria-label="Enviar mensagem">Enviar ↑</button></form></section>`}
function openFinancePage(){return `${heading('Open Finance','Acompanhe saldos, movimentações e investimentos recebidos pelo Meu Pluggy.') }<div class="assistant-note openfinance-note"><span>↗</span><div><b id="openfinance-mode">Verificando conexão local…</b><p>Atualize esta tela para buscar saldos, transações e investimentos. Caixinhas do Nubank devem aparecer como posições de renda fixa, geralmente CDB, quando a Pluggy as disponibilizar.</p></div></div><div class="openfinance-toolbar"><div class="actions"><button class="button primary" id="openfinance-connect" data-action="openfinance-connect" disabled>Conectar Meu Pluggy</button><button class="button" data-action="openfinance-refresh">Atualizar dados</button></div><span id="openfinance-status" class="muted">Verificando servidor local…</span></div><div id="openfinance-data" class="openfinance-data"><div class="empty-state">As conexões do Meu Pluggy aparecerão aqui.</div></div><p class="openfinance-footnote">Saldos e posições são consultados na Pluggy ao abrir ou atualizar esta tela. As caixinhas aparecem separadas do saldo disponível da conta para evitar somar o mesmo dinheiro duas vezes.</p>`}
function responseItems(data){return Array.isArray(data)?data:(Array.isArray(data?.results)?data.results:[])}
function investmentPositions(item){const direct=Array.isArray(item.investments)?item.investments:[];const usedDirect=new Set();const reserved=(item.accounts||[]).flatMap(account=>(account.bankData?.reservedBalances||[]).map((balance,index)=>{const amounts=Array.isArray(balance.availableAmounts)?balance.availableAmounts:[];const value=amounts.length?amounts.reduce((sum,amount)=>sum+Number(amount.amount||0),0):Number(balance.balance??balance.amount??0);return {id:`reserved-${account.id}-${index}`,name:balance.name||'Saldo reservado',type:'Caixinha',subtype:'Saldo reservado',balance:value,currencyCode:account.currencyCode||'BRL',status:'ACTIVE',source:'reserved'};})).filter(balance=>balance.balance>0);const unmatchedReserved=[];for(const balance of reserved){const normalizedName=String(balance.name).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim();const matchIndex=direct.findIndex((investment,index)=>{if(usedDirect.has(index))return false;const directName=String(investment.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim();const sameName=normalizedName&&normalizedName===directName;const sameCdbAmount=String(investment.subtype||'').toUpperCase()==='CDB'&&Math.abs(Number(investment.balance||0)-balance.balance)<0.01;return sameName||sameCdbAmount;});if(matchIndex>=0)usedDirect.add(matchIndex);else unmatchedReserved.push(balance);}return [...direct,...unmatchedReserved];}
function investmentAvailabilityMessage(item){return (item.products||[]).includes('INVESTMENTS')?'A conexão informa que Investimentos está disponível, mas a Pluggy não retornou posições nesta atualização. Verifique se o Meu Pluggy já sincronizou as caixinhas do Nubank.':'A conexão não informou o produto Investimentos. A Pluggy pode não ter recebido as posições de RDB desta conta; confira a sincronização no Meu Pluggy e tente atualizar novamente.';}
function investmentTypeLabel(investment){if(investment.source==='reserved')return 'Caixinha / saldo reservado';const subtype=String(investment.subtype||'').toUpperCase();const issuerText=`${investment.name||''} ${investment.issuer||''}`;if(subtype==='RDB')return 'Caixinha · RDB';if(subtype==='CDB'&&/caixinha|rdb|nubank|nu financeira/i.test(issuerText))return 'Caixinha · CDB/RDB';return [investment.type,investment.subtype].filter(Boolean).join(' · ')||'Investimento';}
function googleSignInButton(){return `<button class="button primary" data-action="google-sign-in">Entrar com Google</button>`}
function accessPage(){return `${heading('Acesso restrito','Entre somente com sua conta Google autorizada.') }<div class="panel auth-panel access-panel"><span class="brand-mark">G</span><h2>GestorPro pessoal</h2><p>Esta instalação permite acesso apenas a <b>${escapeHTML(allowedGoogleEmail||'a conta Google autorizada')}</b>. Nenhuma outra conta Google poderá abrir seus dados.</p>${supabaseClient?googleSignInButton():'<p>O login ainda não foi configurado no servidor.</p>'}</div>`}
function settingsPage(){const access=!supabaseClient?`<p>${requireAuth?'O acesso está bloqueado até configurar o Supabase Auth e o provedor Google no servidor.':'Configure o Supabase Auth e o provedor Google para ativar a entrada restrita.'}</p>`:currentUser?`<p>Sessão conectada como <b>${escapeHTML(currentUser.email||'usuário')}</b>.</p><button class="button" data-action="sign-out">Sair da conta</button>`:`<p>Entre com a conta Google autorizada.</p>${googleSignInButton()}`;return `${heading('Configurações','Preferências do seu controle financeiro.') }<div class="simple-grid"><article class="simple-card"><small>Moeda</small><strong>Real brasileiro</strong><p>Valores exibidos em BRL (R$)</p></article><article class="simple-card"><small>Privacidade</small><strong>Acesso Google restrito</strong><p>${requireAuth?`Somente ${escapeHTML(allowedGoogleEmail||'a conta autorizada')} pode acessar esta instalação.`:'O login restrito será aplicado na hospedagem.'}</p></article><article class="simple-card"><small>Dados</small><strong>${requireAuth?(cloudSyncReady?'Sincronizados na sua conta':'Aguardando sincronização'):'Salvos neste dispositivo'}</strong><p>${requireAuth?'Contas, lançamentos, caixinhas e categorias são sincronizados com a linha protegida por RLS do seu usuário.':'No uso local, os dados permanecem neste navegador.'}</p></article></div><section class="section-title"><h2>Dados locais</h2></section><div class="panel auth-panel"><p>Baixe uma cópia com suas contas e lançamentos para guardar em local seguro. O arquivo contém informações financeiras pessoais.</p><button class="button primary" data-action="export-data">Baixar cópia de segurança</button></div><section class="section-title"><h2>Conta e assistente</h2></section><div class="panel auth-panel">${access}</div>`}function isAllowedGoogleUser(user=currentUser){if(!requireAuth)return true;const emailMatches=Boolean(user&&allowedGoogleEmail&&String(user.email||'').trim().toLowerCase()===allowedGoogleEmail);const providerIsGoogle=user?.app_metadata?.provider==='google';return emailMatches&&providerIsGoogle}
async function apiRequest(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(requireAuth){if(!supabaseClient||!isAllowedGoogleUser())throw new Error('Entre com sua conta Google autorizada.');const {data:{session}}=await supabaseClient.auth.getSession();if(!session?.access_token)throw new Error('Sua sessão Google expirou. Entre novamente.');headers.Authorization=`Bearer ${session.access_token}`;}const response=await fetch(path,{...options,headers});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Não foi possível falar com o servidor.');return data;}
async function loadOpenFinancePage(refreshData=false){if(openFinanceLoading)return;openFinanceLoading=true;const mode=document.getElementById('openfinance-mode'),status=document.getElementById('openfinance-status'),connect=document.getElementById('openfinance-connect');try{openFinanceStatus=await apiRequest('/api/openfinance/status');if(mode)mode.textContent=openFinanceStatus.mode==='sandbox'?'Modo demonstração Pluggy':'Conexão Pluggy pessoal';if(connect)connect.disabled=!openFinanceStatus.configured;if(status)status.textContent=openFinanceStatus.configured?'Servidor local conectado.': 'Configure as credenciais Pluggy no arquivo .env local para conectar.';if(refreshData&&openFinanceItems.length){openFinanceData=[];renderOpenFinanceData();for(const saved of openFinanceItems){try{const item=await apiRequest(`/api/openfinance/items/${encodeURIComponent(saved.id)}`);const institution=item.connector?.name||saved.institution||'Instituição conectada';const accountResponse=await apiRequest(`/api/openfinance/accounts?itemId=${encodeURIComponent(saved.id)}`);const linkedAccounts=responseItems(accountResponse);let investmentError='';const investmentsResponse=await apiRequest(`/api/openfinance/investments?itemId=${encodeURIComponent(saved.id)}`).catch(error=>{investmentError=error.message;return {results:[]};});const details=await Promise.all(linkedAccounts.map(async account=>{const txResponse=await apiRequest(`/api/openfinance/transactions?accountId=${encodeURIComponent(account.id)}`).catch(error=>({results:[],error:error.message}));return {...account,transactions:responseItems(txResponse),transactionError:txResponse.error||''};}));openFinanceData.push({id:saved.id,institution,status:item.status||'UNKNOWN',accounts:details,investments:responseItems(investmentsResponse),investmentError,products:Array.isArray(item.products)?item.products:[]});}catch(error){openFinanceData.push({id:saved.id,institution:saved.institution||'Conexão Pluggy',status:'ERROR',error:error.message,accounts:[],investments:[],investmentError:'',products:[]});}}renderOpenFinanceData();}}catch(error){if(mode)mode.textContent='Servidor local do GestorPro não encontrado';if(status)status.textContent='Abra o projeto local e reinicie o servidor para usar o Open Finance.';if(connect)connect.disabled=true;const target=document.getElementById('openfinance-data');if(target)target.innerHTML='<div class="empty-state">Inicie o servidor local do GestorPro e recarregue esta tela.</div>';}finally{openFinanceLoading=false;if(currentPage==='inicio')render('inicio');}}
function renderOpenFinanceData(){const target=document.getElementById('openfinance-data');if(!target)return;if(!openFinanceData.length){target.innerHTML='<div class="panel openfinance-empty"><b>Nenhuma conexão do Meu Pluggy</b><p>Conecte suas instituições em meu.pluggy.ai e depois autorize o conector MeuPluggy aqui.</p></div>';return;}const allInvestments=openFinanceData.flatMap(investmentPositions);const investedTotal=allInvestments.reduce((sum,investment)=>sum+Number(investment.balance||0),0);const investmentCount=allInvestments.filter(investment=>investment.status!=='TOTAL_WITHDRAWAL').length;target.innerHTML=`<section class="simple-grid investment-summary"><article class="simple-card investment-total"><small>${investmentCount?'Total investido conectado':'Investimentos não informados'}</small><strong>${investmentCount?money(investedTotal):'—'}</strong><p>${investmentCount?`${investmentCount} posição(ões) recebida(s) pela Pluggy`:'A Pluggy não retornou posições; isso não confirma saldo zero.'}</p></article></section>`+openFinanceData.map(item=>`<section class="panel openfinance-item"><div class="openfinance-item-head"><div><span class="eyebrow">${openFinanceStatus?.mode==='sandbox'?'DEMONSTRAÇÃO':'MEU PLUGGY'}</span><h2>${escapeHTML(item.institution)}</h2><p class="muted">Status da conexão: ${escapeHTML(item.status)}</p></div><button class="button" data-action="openfinance-refresh">Atualizar</button></div>${item.error?`<p class="openfinance-error">${escapeHTML(item.error)}</p>`:''}${item.investmentError?`<p class="openfinance-error">Erro ao carregar investimentos: ${escapeHTML(item.investmentError)}</p>`:''}<div class="simple-grid openfinance-account-grid">${item.accounts.map(account=>`<article class="simple-card"><small>${escapeHTML(account.subtype||account.type||'Conta')}</small><strong>${money(Number(account.balance)||0)}</strong><p>${escapeHTML(account.name||account.marketingName||item.institution)} · ${escapeHTML(account.currencyCode||'BRL')}</p></article>`).join('')||'<p class="muted">A Pluggy ainda não retornou contas para esta conexão.</p>'}</div><div class="section-title"><h2>Investimentos e caixinhas</h2><span class="muted">${investmentPositions(item).filter(investment=>investment.status!=='TOTAL_WITHDRAWAL').length?money(investmentPositions(item).filter(investment=>investment.status!=='TOTAL_WITHDRAWAL').reduce((sum,investment)=>sum+Number(investment.balance||0),0)):'—'}</span></div>${investmentPositions(item).filter(investment=>investment.status!=='TOTAL_WITHDRAWAL').length?`<div class="simple-grid investment-grid">${investmentPositions(item).filter(investment=>investment.status!=='TOTAL_WITHDRAWAL').map(investment=>`<article class="simple-card investment-card"><small>${escapeHTML(investmentTypeLabel(investment))}</small><strong>${money(Number(investment.balance)||0)}</strong><p>${escapeHTML(investment.name||investment.issuer||'Posição de investimento')}${investment.status?` · ${escapeHTML(investment.status)}`:''}</p></article>`).join('')}</div>`:`<p class="muted investment-empty">${escapeHTML(investmentAvailabilityMessage(item))}</p>`}${item.accounts.flatMap(account=>account.transactions.map(tx=>({...tx,accountLabel:account.name||account.subtype||'Conta'}))).length?`<div class="section-title"><h2>Movimentações recentes</h2></div><div class="panel table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>DESCRIÇÃO</th><th>CONTA</th><th>DATA</th><th>VALOR</th></tr></thead><tbody>${item.accounts.flatMap(account=>account.transactions.map(tx=>({...tx,accountLabel:account.name||account.subtype||'Conta'}))).sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,30).map(tx=>{const incoming=tx.type==='CREDIT';return `<tr><td><b>${escapeHTML(tx.description||'Movimentação')}</b><div class="muted">${escapeHTML(tx.category||tx.operationType||tx.status||'')}</div></td><td class="muted">${escapeHTML(tx.accountLabel)}</td><td class="muted">${tx.date?formatDate(String(tx.date).slice(0,10)):'—'}</td><td><b class="${incoming?'income-text':'expense-text'}">${incoming?'+':'−'} ${money(Math.abs(Number(tx.amount)||0))}</b></td></tr>`;}).join('')}</tbody></table></div></div>`:'<p class="muted">Nenhuma movimentação retornada ainda.</p>'}</section>`).join('');}
function reportsPage(){const month=totals(monthTransactions());const analysis=spendingAnalysis();const categories=Object.entries(analysis.currentTotals).sort((a,b)=>b[1]-a[1]);return `${heading('Análise financeira','Veja como distribuiu seus gastos e receba alertas quando algo fugir do seu padrão.') }<div class="simple-grid">${[['Entradas',money(month.entrada)],['Saídas',money(month.saida)],['Resultado do mês',money(month.entrada-month.saida)]].map(([label,value])=>`<article class="simple-card"><small>${label} · mês atual</small><strong>${value}</strong><p>Transferências entre suas contas não entram como renda ou gasto.</p></article>`).join('')}</div><section class="section-title"><h2>Gastos para revisar</h2></section>${spendingAlertsMarkup()}<section class="section-title"><h2>Gastos por categoria</h2></section><div class="panel table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>CATEGORIA</th><th>VALOR NO MÊS</th><th>PARTE DAS SAÍDAS</th></tr></thead><tbody>${categories.map(([name,value])=>`<tr><td><b>${escapeHTML(name)}</b></td><td>${money(value)}</td><td>${month.saida?Math.round(value/month.saida*100):0}%</td></tr>`).join('')||'<tr><td colspan="3" class="empty-state">Sem despesas categorizadas neste período.</td></tr>'}</tbody></table></div></div><p class="openfinance-footnote">Os alertas são comparações automáticas, não uma conclusão de que o gasto foi um erro. Revise a descrição e a categoria antes de tomar decisões.</p>`}
function render(page=currentPage){currentPage=page;const visiblePage=requireAuth&&!isAllowedGoogleUser()?'acesso':page;document.getElementById('breadcrumb').textContent=visiblePage==='acesso'?'Acesso':pageNames[visiblePage]||pageNames.inicio;document.title=`GestorPro — ${visiblePage==='acesso'?'Acesso restrito':pageNames[visiblePage]||pageNames.inicio}`;const views={inicio:dashboard,contas:accountsPage,lancamentos:transactionsPage,assistente:assistantPage,openfinance:openFinancePage,planejamento:planningPage,relatorios:reportsPage,configuracoes:settingsPage,acesso:accessPage,ajuda:()=>`${heading('Central de ajuda','Dicas para organizar suas finanças pessoais.')}`};document.getElementById('page-content').innerHTML=(views[visiblePage]||dashboard)();document.querySelectorAll('.nav-item').forEach(item=>item.classList.toggle('active',item.dataset.page===visiblePage));const accountCount=document.querySelector('.nav-count');if(accountCount)accountCount.textContent=displayAccounts().length;document.getElementById('sidebar').classList.remove('open');bindSearch();if(visiblePage==='openfinance')loadOpenFinancePage(true)}
function showToast(message){const element=document.getElementById('toast');element.textContent=message;element.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>element.classList.remove('show'),2600)}
function openForm(kind,id=null){
  const modal=document.getElementById('modal'),content=document.getElementById('modal-content');
  if(kind==='account'){
    content.innerHTML=`<h2>Adicionar conta</h2><p>Informe um nome e o saldo atual. Não informe senha nem dados de acesso ao banco.</p><div class="form-field"><label>Nome para identificar</label><input name="name" required placeholder="Ex.: Conta principal"></div><div class="form-field"><label>Instituição (opcional)</label><input name="institution" placeholder="Ex.: Meu banco"></div><div class="form-field"><label>Tipo de conta</label><select name="type"><option>Conta corrente</option><option>Poupança</option><option>Investimento</option><option>Carteira digital</option></select></div><div class="form-field"><label>Saldo atual (R$)</label><input name="balance" type="number" step="0.01" required value="0"></div>`;
  }else if(kind==='savings-pot'){
    const pot=savingsPots.find(item=>item.id===id)||{};
    content.innerHTML=`<h2>${pot.id?'Atualizar caixinha':'Adicionar caixinha'}</h2><p>Informe o saldo que você vê no Nubank. Este valor será identificado como informado manualmente.</p><div class="form-field"><label>Nome da caixinha</label><input name="name" required maxlength="60" placeholder="Ex.: Reserva de emergência" value="${escapeHTML(pot.name||'')}" /></div><div class="form-field"><label>Saldo atual (R$)</label><input name="balance" type="number" min="0" step="0.01" required placeholder="0,00" value="${pot.id?Number(pot.balance||0):''}" /></div><div class="form-field"><label>Meta (R$) · opcional</label><input name="goal" type="number" min="0" step="0.01" placeholder="Ex.: 10000,00" value="${pot.goal?Number(pot.goal):''}" /></div>`;
  }else{
    const prefill=pendingAssistantSuggestion||{};
    const selectableAccounts=displayAccounts();
    content.innerHTML=`<h2>Novo lançamento</h2><p>Registre uma entrada ou saída em uma conta conectada ou manual.</p><div class="form-field"><label>Descrição</label><input name="description" required placeholder="Ex.: Conta de luz" value="${escapeHTML(prefill.description||'')}"></div><div class="form-field"><label>Tipo</label><select name="kind" id="transaction-kind"><option value="saida" ${prefill.kind==='saida'?'selected':''}>Saída</option><option value="entrada" ${prefill.kind==='entrada'?'selected':''}>Entrada</option><option value="transferencia" ${prefill.kind==='transferencia'?'selected':''}>Transferência entre minhas contas</option></select></div><div class="form-field"><label>Categoria</label><select name="category" id="transaction-category" required>${[...new Set([prefill.category||'Sem categoria',...spendingCategories].filter(Boolean))].map(category=>`<option value="${escapeHTML(category)}" ${(prefill.category||'Sem categoria')===category?'selected':''}>${escapeHTML(category)}</option>`).join('')}</select></div><div class="form-field"><label>Conta de origem</label><select name="accountId" required>${selectableAccounts.map(account=>`<option value="${account.id}">${escapeHTML(account.name)}</option>`).join('')}</select></div><div class="form-field destination-field" id="destination-field"><label>Conta de destino</label><select name="toAccountId" id="destination-account" disabled>${selectableAccounts.map(account=>`<option value="${account.id}">${escapeHTML(account.name)}</option>`).join('')}</select></div><div class="form-field"><label>Valor (R$)</label><input name="amount" type="number" min="0.01" step="0.01" required placeholder="0,00"></div><div class="form-field"><label>Data</label><input name="date" type="date" required value="${new Date().toISOString().slice(0,10)}"></div>`;
  }
  content.insertAdjacentHTML('beforeend',`<div class="modal-actions"><button class="button" type="button" data-modal-close>Cancelar</button><button class="button primary" type="submit" value="save">Salvar</button></div>`);
  modal.showModal();
  const kindField=document.getElementById('transaction-kind'),destinationField=document.getElementById('destination-field'),destinationSelect=document.getElementById('destination-account');
  if(kindField){const syncDestination=()=>{const enabled=kindField.value==='transferencia';destinationField.classList.toggle('visible',enabled);destinationSelect.disabled=!enabled;destinationSelect.required=enabled;};kindField.addEventListener('change',syncDestination);syncDestination();}
  document.getElementById('modal-form').onsubmit=event=>{
    if(event.submitter?.value!=='save')return;event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget).entries());
    if(kind==='account'){accounts.unshift({id:`acc-${Date.now()}`,name:data.name,institution:data.institution||'Instituição não informada',type:data.type,balance:Number(data.balance),color:['blue','purple','green'][accounts.length%3]});showToast('Conta adicionada.');}
    else if(kind==='savings-pot'){const now=new Date().toISOString();const existing=savingsPots.find(item=>item.id===id);const balance=Number(data.balance)||0;const history=Array.isArray(existing?.history)?existing.history:[];if(!history.length||Number(history.at(-1).balance)!==balance)history.push({date:now.slice(0,10),balance});if(existing){Object.assign(existing,{name:data.name,balance,goal:Number(data.goal)||0,history,updatedAt:now});showToast('Caixinha e evolução atualizadas.');}else{savingsPots.unshift({id:`pot-${Date.now()}`,name:data.name,balance,goal:Number(data.goal)||0,history,updatedAt:now});showToast('Caixinha adicionada.');}if(!saveSavingsPots())return;}
    else{
      if(data.kind==='transferencia'&&data.accountId===data.toAccountId){showToast('Escolha contas diferentes para a transferência.');return;}
      transactions.unshift({id:`tx-${Date.now()}`,description:data.description,category:data.category,accountId:data.accountId,toAccountId:data.kind==='transferencia'?data.toAccountId:null,date:data.date,kind:data.kind,amount:Number(data.amount)});
      const source=accounts.find(item=>item.id===data.accountId),destination=accounts.find(item=>item.id===data.toAccountId),amount=Number(data.amount);
      if(source)source.balance+=data.kind==='entrada'?amount:-amount;if(data.kind==='transferencia'&&destination)destination.balance+=amount;
      pendingAssistantSuggestion=null;showToast(data.kind==='transferencia'?'Transferência registrada.':'Lançamento adicionado.');
    }
    if(kind!=='savings-pot')saveLocalData();modal.close();render(currentPage);
  };
}
function bindSearch(){const field=document.getElementById('transaction-search');if(field)field.addEventListener('input',()=>{const query=field.value.toLocaleLowerCase('pt-BR');const filtered=allTransactions().filter(item=>`${item.description} ${item.category} ${accountName(item.accountId)}`.toLocaleLowerCase('pt-BR').includes(query));document.getElementById('transaction-table').innerHTML=transactionTable(filtered);});}
async function sendAssistantMessage(rawText){
  const text=rawText.trim();if(!text||text.length>500)return;
  const history=assistantMessages.slice(-8).map(item=>({role:item.role,text:item.text}));
  assistantMessages.push({role:'user',text},{role:'assistant',text:'Analisando a descrição…',loading:true});render('assistente');
  try{
    let result;
    if(supabaseClient){
      const {data:{session}}=await supabaseClient.auth.getSession();
      if(!session){throw new Error('Entre ou crie sua conta em Configurações para ativar a análise OpenAI.');}
      const {data,error}=await supabaseClient.functions.invoke('categorize-transaction',{body:{message:text,history}});
      if(error)throw new Error('Não consegui acessar o assistente. Confira se a função foi configurada e publicada.');
      const typeMap={expense:'saida',income:'entrada',transfer:'transferencia',uncertain:null};
      result={category:data.category,kind:typeMap[data.transaction_type]??null,reason:data.explanation,reply:data.reply,confidence:data.confidence,ambiguous:data.confidence==='low'||data.transaction_type==='uncertain'};
    }else result=suggestCategory(text);
    assistantMessages.pop();lastSuggestion={description:text,...result};
    assistantMessages.push({role:'assistant',text:result.reply||(result.ambiguous?'Encontrei uma possibilidade, mas confira o contexto antes de salvar.':'Esta é minha sugestão com base na descrição. Confira se faz sentido antes de registrar.'),description:text,category:result.category,kind:result.kind,reason:result.reason||result.explanation,confidence:result.confidence});
  }catch(error){assistantMessages.pop();assistantMessages.push({role:'assistant',text:error.message||'Não consegui analisar agora. Tente novamente.'});}
  render('assistente');document.getElementById('assistant-input')?.focus();
}
document.addEventListener('submit',async event=>{
  if(event.target.id==='assistant-form'){event.preventDefault();const data=new FormData(event.target);const input=document.getElementById('assistant-input');if(input)input.disabled=true;await sendAssistantMessage(String(data.get('message')||''));return;}
});
document.addEventListener('change',event=>{const field=event.target.closest('[data-transaction-category]');if(!field)return;transactionCategoryOverrides[field.dataset.transactionCategory]=field.value;if(saveCategoryOverrides()){showToast('Categoria atualizada e salva neste navegador.');render(currentPage);}});
document.addEventListener('click',async event=>{if(event.target.closest('[data-action="google-sign-in"]')){if(!supabaseClient){showToast('O login Google ainda não está configurado.');return;}if(!allowedGoogleEmail){showToast('O GestorPro ainda não tem uma conta Google autorizada configurada.');return;}const {error}=await supabaseClient.auth.signInWithOAuth({provider:'google',options:{redirectTo:authRedirectUrl}});if(error)showToast(error.message);return;}if(event.target.closest('[data-modal-close],.modal-close')){document.getElementById('modal').close();return;}const prompt=event.target.closest('[data-prompt]');if(prompt){sendAssistantMessage(prompt.dataset.prompt);return;}const page=event.target.closest('[data-page]');if(page){render(page.dataset.page);return;}const target=event.target.closest('[data-action]');const action=target?.dataset.action;if(action==='new-account')openForm('account');if(action==='new-transaction')openForm('transaction');if(action==='new-savings-pot')openForm('savings-pot');if(action==='update-savings-pot')openForm('savings-pot',target.dataset.id);if(action==='delete-savings-pot'){savingsPots=savingsPots.filter(pot=>pot.id!==target.dataset.id);saveSavingsPots();render(currentPage);showToast('Caixinha removida do acompanhamento.');}if(action==='export-data')exportLocalData();if(action==='openfinance-connect')startOpenFinanceConnect();if(action==='openfinance-refresh')loadOpenFinancePage(true);if(action==='use-suggestion'){pendingAssistantSuggestion={description:target.dataset.description,category:target.dataset.category,kind:target.dataset.kind||null};openForm('transaction');}if(action==='sign-out'&&supabaseClient){await supabaseClient.auth.signOut();currentUser=null;showToast('Você saiu da conta.');render('configuracoes');}});
loadLocalData();
loadOpenFinanceItems();
loadSavingsPots();
loadCategoryOverrides();
if(supabaseClient){supabaseClient.auth.onAuthStateChange((event,session)=>{const user=session?.user||null;if(requireAuth&&user&&!isAllowedGoogleUser(user)){currentUser=null;cloudSyncReady=false;showToast('Esta conta Google não está autorizada.');setTimeout(()=>supabaseClient.auth.signOut(),0);render(currentPage);return;}currentUser=user;if(!user){cloudSyncReady=false;openFinanceData=[];render(currentPage);return;}render(currentPage);if(event==='INITIAL_SESSION'||event==='SIGNED_IN')loadCloudWorkspace(user);});}
document.getElementById('mobile-menu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('today').textContent=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date());
render('inicio');
if(openFinanceItems.length&&(!requireAuth||isAllowedGoogleUser()))loadOpenFinancePage(true);
